syntax:
template<typename T> class ClassName { /* general template definition */ };
// Explicit specialization
template<> class ClassName<SpecificType> { /* specialized implementation for SpecificType */ };
// Implicit instantiation occurs when the template is used in code requiring its definition, e.g., creating an object or calling a member function.

code_example:
#include <iostream>
template<typename T>
class Calculator {
public:
    void compute() {
        std::cout << "Generic compute for type" << std::endl;
    }
};
// Explicit specialization for int
template<>
class Calculator<int> {
public:
    void compute() {
        std::cout << "Specialized compute for int" << std::endl;
    }
};
int main() {
    Calculator<double> calcDouble; // Implicit instantiation of generic template
    calcDouble.compute();
    Calculator<int> calcInt; // Explicit specialization instantiation
    calcInt.compute();
    return 0;
}
